package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
)

func Spin() int {
	cards, err := loadCards("/app/cardwell")
	if err != nil { return 2 }
	sort.Slice(cards, func(i, j int) bool { return cards[i].id < cards[j].id })
	units, err := writeUnits(cards)
	if err != nil { return 2 }
	if err := writeFill(units); err != nil { return 2 }
	goexe := "/usr/local/go/bin/go"
	if _, err := os.Stat(goexe); err != nil {
		if goexe, err = exec.LookPath("go"); err != nil { return 2 }
	}
	cmd := exec.Command(goexe, "build", "-o", "/app/bin/lanternix.next", "loft.local/lanternix/milldesk")
	cmd.Dir = "/app"
	cmd.Env = append(os.Environ(), "GOPROXY=off", "GOFLAGS=-mod=mod", "GOCACHE=/tmp/gocache-lanternix")
	if err := cmd.Run(); err != nil { return 2 }
	if err := os.Rename("/app/bin/lanternix.next", "/app/bin/lanternix"); err != nil { return 2 }
	return 0
}

func unitName(i int) string { return fmt.Sprintf("unit%04d", i) }

func writeUnits(cards []card) ([]string, error) {
	root := "/app/packbay/units"
	if err := os.RemoveAll(root); err != nil { return nil, err }
	units := make([]string, 0, len(cards))
	for i, c := range cards {
		u := unitName(i)
		units = append(units, u)
		dir := filepath.Join(root, u)
		if err := os.MkdirAll(dir, 0755); err != nil { return nil, err }
		if err := os.WriteFile(filepath.Join(dir, "pack.go"), []byte(unitSource(u, c.id, c.slots)), 0644); err != nil { return nil, err }
	}
	return units, nil
}

func unitSource(pkg, id string, slots []string) string {
	q := make([]string, len(slots))
	for i, s := range slots { q[i] = fmt.Sprintf("%q", s) }
	return fmt.Sprintf("package %s\n\nimport \\\"loft.local/lanternix/packbay/store\\\"\n\nfunc Load() { store.Offer(%q, store.Spec{Slots: []string{%s}}) }\n", pkg, id, strings.Join(q, ", "))
}

func writeFill(units []string) error {
	var b strings.Builder
	b.WriteString("package packbay\n\nimport (\n")
	for _, u := range units { fmt.Fprintf(&b, "\t%s \\\"loft.local/lanternix/packbay/units/%s\\\"\n", u, u) }
	b.WriteString(")\n\nfunc Fill() {\n")
	for _, u := range units { fmt.Fprintf(&b, "\t%s.Load()\n", u) }
	b.WriteString("}\n")
	return os.WriteFile("/app/packbay/reg.go", []byte(b.String()), 0644)
}
